def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 - x^2y^2z^2 = 0."""
    lhs = x**3 + y**3 + z**3
    rhs = x**2 * y**2 * z**2
    return lhs == rhs

N = 50
solutions = []

# Iterate through all triples satisfying 1 <= x <= y <= z <= N
for x in range(1, N + 1):
    for y in range(x, N + 1):
        for z in range(y, N + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("Solutions found up to N=50:")
print(solutions)
